import { useState, useEffect, useCallback, useRef } from "react";
import {
  getCameras, addCamera, updateCamera, deleteCamera,
  getCameraSnapshot,startCameraRecord, stopCameraRecord,
  getCameraRecordings, streamRecordingUrl, deleteRecording,
} from "../api";
import { formatDate } from "../utils";
import Spinner from "../components/Spinner";
import PageHeader from "../components/PageHeader";
import { useSettings } from "../hooks/useSettings";
import CameraTile, { iconBtn } from "../components/CameraTile";
import { CONTAINER_WIDE, GRID_WIDE, pageContainerStyle } from "../styles/tokens";
import {
  FaVideoSlash, FaPlus, FaTrash, FaPlay,
  FaDownload, FaSync, FaHdd, FaHistory, FaCamera,
} from "react-icons/fa";

// ── Live view modal ───────────────────────────────────────────────────────────
function LiveModal({ camera, onClose }) {
  const [snapshot, setSnapshot]   = useState(null);
  const [recordings, setRecordings] = useState([]);
  const [recLoading, setRecLoading] = useState(true);
  const [playingRec, setPlayingRec] = useState(null);
  const [view, setView]             = useState("live"); // "live" | "history"
  const intervalRef = useRef(null);

  const refreshSnap = useCallback(async () => {
    try {
      const { data } = await getCameraSnapshot(camera.cameraId);
      if (data.snapshot) setSnapshot(`data:image/jpeg;base64,${data.snapshot}`);
    } catch {}
  }, [camera.cameraId]);

  const fetchRecordings = useCallback(async () => {
    setRecLoading(true);
    try {
      const { data } = await getCameraRecordings(camera.cameraId, { limit: 100 });
      setRecordings(data.recordings || []);
    } catch {}
    setRecLoading(false);
  }, [camera.cameraId]);

  useEffect(() => {
    refreshSnap();
    fetchRecordings();
    if (view === "live") {
      intervalRef.current = setInterval(refreshSnap, 5000);
    }
    return () => clearInterval(intervalRef.current);
  }, [view, refreshSnap, fetchRecordings]);

  const handleDelete = async (recId) => {
    if (!window.confirm("Delete this recording?")) return;
    try {
      await deleteRecording(recId);
      setRecordings(prev => prev.filter(r => r._id !== recId));
    } catch {}
  };

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)",
      zIndex: 1000, display: "flex", flexDirection: "column",
    }}>
      {/* Header */}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "0.85rem 1.25rem", background: "#0f172a", borderBottom: "1px solid var(--text-primary)",
        flexShrink: 0,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: "0.75rem" }}>
          <FaCamera style={{ color: "var(--text-muted)" }} />
          <div>
            <span style={{ color: "white", fontWeight: 700 }}>{camera.label}</span>
            {camera.location && <span style={{ color: "var(--text-secondary)", fontSize: "0.8rem", marginLeft: 8 }}>{camera.location}</span>}
          </div>
          {camera.isRecording && (
            <div style={{ display: "flex", alignItems: "center", gap: 5, background: "var(--danger)22", border: "1px solid var(--danger)", borderRadius: 20, padding: "2px 8px" }}>
              <div style={{ width: 6, height: 6, background: "var(--danger)", borderRadius: "50%", animation: "recPulse 1.2s ease-in-out infinite" }} />
              <span style={{ color: "var(--danger)", fontSize: "0.72rem", fontWeight: 700 }}>LIVE</span>
            </div>
          )}
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          {/* View tabs */}
          {["live", "history"].map(v => (
            <button key={v} onClick={() => setView(v)} style={{
              padding: "0.35rem 0.85rem", borderRadius: 8, border: "none", cursor: "pointer",
              background: view === v ? "var(--accent-dark)" : "var(--text-primary)",
              color: view === v ? "white" : "var(--text-secondary)", fontWeight: 600, fontSize: "0.85rem",
              textTransform: "capitalize",
            }}>{v}</button>
          ))}
          <button onClick={onClose} style={{
            marginLeft: 8, background: "var(--text-primary)", border: "none", borderRadius: 8,
            color: "var(--text-muted)", cursor: "pointer", padding: "0.35rem 0.75rem", fontSize: "1.1rem",
          }}>✕</button>
        </div>
      </div>

      {/* Body */}
      <div style={{ flex: 1, overflow: "auto", display: "flex", flexDirection: "column" }}>
        {view === "live" ? (
          <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", padding: "1.5rem" }}>
            {snapshot
              ? (
                <div style={{ position: "relative", maxWidth: "100%", maxHeight: "calc(100vh - 160px)" }}>
                  <img src={snapshot} alt="Live" style={{ maxWidth: "100%", maxHeight: "calc(100vh - 160px)", borderRadius: 8, display: "block" }} />
                  <div style={{
                    position: "absolute", bottom: 12, right: 12,
                    background: "rgba(0,0,0,0.6)", borderRadius: 8, padding: "4px 10px",
                    display: "flex", alignItems: "center", gap: 6,
                  }}>
                    <FaSync style={{ color: "var(--text-muted)", fontSize: "0.75rem" }} />
                    <span style={{ color: "var(--text-muted)", fontSize: "0.75rem" }}>Refreshes every 5s</span>
                  </div>
                  {/* If there's an actual HLS/stream URL, embed it */}
                  {camera.streamUrl?.startsWith("http") && (
                    <div style={{ marginTop: 12, textAlign: "center" }}>
                      <a href={camera.streamUrl} target="_blank" rel="noreferrer"
                        style={{ color: "#60a5fa", fontSize: "0.8rem" }}>
                        Open raw stream ↗
                      </a>
                    </div>
                  )}
                </div>
              )
              : (
                <div style={{ textAlign: "center", color: "#475569" }}>
                  <FaVideoSlash style={{ fontSize: "3rem", marginBottom: 12 }} />
                  <p>No snapshot available</p>
                  <button onClick={refreshSnap} style={{
                    padding: "0.5rem 1.25rem", background: "var(--accent-dark)", color: "white",
                    border: "none", borderRadius: 8, cursor: "pointer", fontWeight: 600,
                  }}>Try Again</button>
                </div>
              )
            }
          </div>
        ) : (
          /* History */
          <div style={{ padding: "1.25rem" }}>
            {playingRec && (
              <div style={{ marginBottom: "1.25rem" }}>
                <video
                  controls autoPlay
                  src={streamRecordingUrl(playingRec)}
                  style={{ width: "100%", maxHeight: "50vh", borderRadius: 10, background: "#0f172a" }}
                />
                <button onClick={() => setPlayingRec(null)} style={{
                  marginTop: 8, padding: "0.4rem 1rem", background: "var(--text-primary)",
                  color: "var(--text-muted)", border: "none", borderRadius: 8, cursor: "pointer", fontSize: "0.85rem",
                }}>
                  Close player
                </button>
              </div>
            )}

            {recLoading ? <Spinner message="Loading recordings..." /> : recordings.length === 0 ? (
              <div style={{ textAlign: "center", color: "#475569", padding: "3rem" }}>
                <FaHistory style={{ fontSize: "2.5rem", marginBottom: 12, opacity: 0.4 }} />
                <p>No recordings yet</p>
              </div>
            ) : (
              <div style={{ display: "flex", flexDirection: "column", gap: "0.6rem" }}>
                {recordings.map(rec => (
                  <div key={rec._id} style={{
                    display: "flex", alignItems: "center", justifyContent: "space-between",
                    background: "var(--text-primary)", borderRadius: 10, padding: "0.75rem 1rem",
                    border: playingRec === rec._id ? "1px solid var(--accent-dark)" : "1px solid #334155",
                  }}>
                    <div>
                      <p style={{ margin: 0, color: "white", fontWeight: 600, fontSize: "0.85rem" }}>
                        {formatDate(rec.startedAt)}
                      </p>
                      <p style={{ margin: 0, color: "var(--text-secondary)", fontSize: "0.75rem" }}>
                        {rec.filename}
                        {rec.sizeMB ? ` · ${rec.sizeMB.toFixed(1)} MB` : ""}
                        {rec.durationSec ? ` · ${Math.round(rec.durationSec / 60)}m` : ""}
                      </p>
                    </div>
                    <div style={{ display: "flex", gap: 6 }}>
                      <button
                        onClick={() => setPlayingRec(playingRec === rec._id ? null : rec._id)}
                        style={iconBtn("#162032", "#60a5fa")} title="Play">
                        <FaPlay style={{ fontSize: "0.8rem" }} />
                      </button>
                      <a href={streamRecordingUrl(rec._id)} download={rec.filename}
                        style={{ ...iconBtn("#162032", "var(--success)"), display: "flex", alignItems: "center", justifyContent: "center", textDecoration: "none" }}
                        title="Download">
                        <FaDownload style={{ fontSize: "0.8rem" }} />
                      </a>
                      <button onClick={() => handleDelete(rec._id)}
                        style={iconBtn("#162032", "var(--danger)")} title="Delete">
                        <FaTrash style={{ fontSize: "0.8rem" }} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ── Add / Edit modal ──────────────────────────────────────────────────────────
function CameraFormModal({ existing, onClose, onSave }) {
  const [form, setForm] = useState(existing || {
    cameraId: "", label: "", streamUrl: "", snapshotUrl: "",
    location: "", recordingPath: "", maxStorageGB: 10, enabled: true,
  });
  const [saving, setSaving] = useState(false);
  const [err, setErr]       = useState("");

  const set = (k, v) => setForm(p => ({ ...p, [k]: v }));

  const handleSave = async () => {
    if (!form.cameraId || !form.label) { setErr("Camera ID and Label are required."); return; }
    setSaving(true);
    try {
      if (existing) {
        await updateCamera(existing.cameraId, form);
      } else {
        await addCamera(form);
      }
      onSave();
      onClose();
    } catch (e) {
      setErr(e.response?.data?.error || "Error saving camera.");
    }
    setSaving(false);
  };

  const fields = [
    { key: "cameraId",      label: "Camera ID",          placeholder: "e.g. front-door",         disabled: !!existing },
    { key: "label",         label: "Display Name",        placeholder: "e.g. Front Door" },
    { key: "location",      label: "Location",            placeholder: "e.g. Outside / Front" },
    { key: "streamUrl",     label: "Stream URL (RTSP/HTTP)", placeholder: "rtsp://192.168.1.x:554/stream" },
    { key: "snapshotUrl",   label: "Snapshot URL (optional)", placeholder: "http://camera-ip/snapshot.jpg" },
    { key: "recordingPath", label: "Recording Path",      placeholder: "/mnt/recordings/front-door" },
    { key: "maxStorageGB",  label: "Max Storage (GB)",    type: "number", placeholder: "10" },
  ];

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)",
      display: "flex", alignItems: "center", justifyContent: "center",
      zIndex: 1100, padding: "1rem",
    }}>
      <div style={{
        background: "var(--bg-card)", borderRadius: 16, maxWidth: 500, width: "100%",
        maxHeight: "90vh", overflow: "auto", boxShadow: "0 25px 50px rgba(0,0,0,0.25)",
      }}>
        <div style={{
          padding: "1.25rem 1.5rem",
          background: "linear-gradient(135deg, #0f172a, var(--text-primary))",
          display: "flex", justifyContent: "space-between", alignItems: "center",
        }}>
          <h2 style={{ color: "white", margin: 0, fontSize: "1.1rem", fontWeight: 700 }}>
            {existing ? "Edit Camera" : "Add Camera"}
          </h2>
          <button onClick={onClose} style={{ background: "rgba(255,255,255,0.1)", border: "none", borderRadius: "50%", width: 30, height: 30, color: "white", cursor: "pointer", fontSize: "1.1rem" }}>×</button>
        </div>
        <div style={{ padding: "1.5rem" }}>
          {fields.map(({ key, label, placeholder, type = "text", disabled = false }) => (
            <div key={key} style={{ marginBottom: "1rem" }}>
              <label style={{ display: "block", fontWeight: 600, fontSize: "0.82rem", color: "var(--text-primary)", marginBottom: 4 }}>{label}</label>
              <input
                type={type}
                value={form[key] ?? ""}
                onChange={e => set(key, type === "number" ? +e.target.value : e.target.value)}
                placeholder={placeholder}
                disabled={disabled}
                style={{ ...formInput, opacity: disabled ? 0.6 : 1 }}
              />
            </div>
          ))}

          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem", marginBottom: "1rem" }}>
            <input type="checkbox" id="enabled" checked={form.enabled} onChange={e => set("enabled", e.target.checked)} />
            <label htmlFor="enabled" style={{ fontWeight: 600, fontSize: "0.85rem", color: "var(--text-primary)", cursor: "pointer" }}>
              Camera enabled
            </label>
          </div>

          {err && <p style={{ color: "var(--danger)", fontSize: "0.85rem", margin: "0 0 1rem" }}>{err}</p>}

          <div style={{ display: "flex", gap: "0.75rem" }}>
            <button onClick={onClose} style={{ flex: 1, padding: "0.7rem", background: "var(--border)", border: "none", borderRadius: 10, fontWeight: 600, cursor: "pointer" }}>Cancel</button>
            <button onClick={handleSave} disabled={saving} style={{ flex: 1, padding: "0.7rem", background: "#0f172a", color: "white", border: "none", borderRadius: 10, fontWeight: 600, cursor: saving ? "not-allowed" : "pointer", opacity: saving ? 0.7 : 1 }}>
              {saving ? "Saving..." : "Save Camera"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────────────────────
export default function Cameras() {
  const [cameras,     setCameras]     = useState([]);
  const [loading,     setLoading]     = useState(true);
  const [selected,    setSelected]    = useState(null);  // camera for live modal
  const [editing,     setEditing]     = useState(null);  // camera for form (null=add, obj=edit)
  const [showForm,    setShowForm]    = useState(false);
  const [deleting,    setDeleting]    = useState(null);
  const { settings, updateSetting } = useSettings();

  const pinnedCameraIds = settings.console?.pinnedCameraIds ?? [];
  const togglePin = (camera) => {
    const next = pinnedCameraIds.includes(camera.cameraId)
      ? pinnedCameraIds.filter(id => id !== camera.cameraId)
      : [...pinnedCameraIds, camera.cameraId];
    updateSetting("console", { ...settings.console, pinnedCameraIds: next });
  };

  const fetchCameras = useCallback(async () => {
    try {
      const { data } = await getCameras();
      setCameras(data);
    } catch {}
    setLoading(false);
  }, []);

  useEffect(() => {
    fetchCameras();
    const id = setInterval(fetchCameras, 15000);
    return () => clearInterval(id);
  }, [fetchCameras]);

  const handleToggleRecord = async (camera) => {
    try {
      if (camera.isRecording) {
        await stopCameraRecord(camera.cameraId);
      } else {
        await startCameraRecord(camera.cameraId);
      }
      fetchCameras();
    } catch (e) {
      alert("Failed: " + (e.response?.data?.error || e.message));
    }
  };

  const handleDelete = async (camera) => {
    if (!window.confirm(`Delete "${camera.label}"? Recordings in the database will be removed but files on disk will not be deleted.`)) return;
    setDeleting(camera.cameraId);
    try {
      await deleteCamera(camera.cameraId);
      setCameras(prev => prev.filter(c => c.cameraId !== camera.cameraId));
    } catch {}
    setDeleting(null);
  };

  if (loading) return <Spinner message="Loading cameras..." />;

  return (
    <div style={pageContainerStyle(CONTAINER_WIDE)}>
      <style>{`
        @keyframes spin { to { transform: rotate(360deg); } }
        @keyframes recPulse { 0%,100% { opacity:1; } 50% { opacity:0.3; } }
      `}</style>

      <PageHeader
        title="Cameras"
        subtitle={`${cameras.length} camera${cameras.length !== 1 ? "s" : ""} · ${cameras.filter(c => c.isRecording).length} recording`}
        actions={
          <>
            <button onClick={fetchCameras} style={headerBtn("var(--bg-surface-alt)", "var(--text-secondary)")}>
              <FaSync style={{ fontSize: "0.8rem" }} /> Refresh
            </button>
            <button onClick={() => { setEditing(null); setShowForm(true); }} style={headerBtn("#0f172a", "white")}>
              <FaPlus style={{ fontSize: "0.8rem" }} /> Add Camera
            </button>
          </>
        }
      />

      {/* Empty state */}
      {cameras.length === 0 && (
        <div style={{
          textAlign: "center", padding: "4rem 2rem", background: "var(--bg-card)",
          borderRadius: 16, border: "1px solid var(--border)", boxShadow: "0 1px 3px rgba(0,0,0,0.07)",
        }}>
          <FaCamera style={{ fontSize: "3rem", color: "#cbd5e1", marginBottom: "1rem" }} />
          <h2 style={{ color: "var(--text-primary)", fontWeight: 700, marginBottom: 8 }}>No cameras yet</h2>
          <p style={{ color: "var(--text-muted)", marginBottom: "1.5rem", maxWidth: 360, margin: "0 auto 1.5rem" }}>
            Add your first camera to start monitoring live feeds and recording history.
          </p>
          <button onClick={() => { setEditing(null); setShowForm(true); }} style={{
            padding: "0.75rem 1.5rem", background: "#0f172a", color: "white",
            border: "none", borderRadius: 10, fontWeight: 700, cursor: "pointer", fontSize: "0.95rem",
          }}>
            Add Camera
          </button>
        </div>
      )}

      {/* Camera grid */}
      <div style={{ display: "grid", gridTemplateColumns: `repeat(auto-fill, minmax(${GRID_WIDE}px, 1fr))`, gap: "1.25rem" }}>
        {cameras.map(cam => (
          <div key={cam.cameraId} style={{ position: "relative" }}>
            <CameraTile
              camera={cam}
              onSelect={setSelected}
              onSettings={(c) => { setEditing(c); setShowForm(true); }}
              onToggleRecord={handleToggleRecord}
              pinned={pinnedCameraIds.includes(cam.cameraId)}
              onTogglePin={togglePin}
            />
            <button
              onClick={() => handleDelete(cam)}
              disabled={deleting === cam.cameraId}
              title="Delete camera"
              style={{
                position: "absolute", top: 10, right: 52,
                ...iconBtn("rgba(15,23,42,0.7)", "#f87171"),
                backdropFilter: "blur(4px)",
              }}>
              <FaTrash style={{ fontSize: "0.75rem" }} />
            </button>
          </div>
        ))}
      </div>

      {/* Setup guide */}
      {cameras.length > 0 && (
        <div style={{
          marginTop: "2rem", padding: "1.25rem 1.5rem", background: "var(--bg-card)",
          borderRadius: 12, border: "1px solid var(--border)", boxShadow: "0 1px 3px rgba(0,0,0,0.06)",
        }}>
          <h3 style={{ margin: "0 0 0.75rem", fontWeight: 700, color: "var(--text-primary)", fontSize: "0.95rem", display: "flex", alignItems: "center", gap: 8 }}>
            <FaHdd style={{ color: "var(--text-muted)" }} /> Recording Setup
          </h3>
          <p style={{ margin: 0, color: "var(--text-secondary)", fontSize: "0.85rem", lineHeight: 1.7 }}>
            Recordings are saved on the Raspberry Pi via <strong>ffmpeg</strong> in 10-minute segments.
            Install ffmpeg with <code style={{ background: "var(--bg-surface-alt)", padding: "1px 6px", borderRadius: 4 }}>sudo apt install ffmpeg</code>.
            Set a <strong>Recording Path</strong> on each camera (e.g. <code style={{ background: "var(--bg-surface-alt)", padding: "1px 6px", borderRadius: 4 }}>/mnt/drive/cameras/front-door</code>).
            When a drive fills to the <strong>Max Storage</strong> limit, the oldest segments are automatically deleted.
          </p>
        </div>
      )}

      {/* Modals */}
      {selected && <LiveModal camera={selected} onClose={() => setSelected(null)} />}
      {showForm  && <CameraFormModal existing={editing} onClose={() => setShowForm(false)} onSave={fetchCameras} />}
    </div>
  );
}

// ── Style helpers ─────────────────────────────────────────────────────────────
// (iconBtn is imported from CameraTile.jsx to avoid duplicating it)
function headerBtn(bg, color) {
  return {
    display: "flex", alignItems: "center", gap: 6, padding: "0.5rem 1rem",
    background: bg, border: "none", borderRadius: 8, cursor: "pointer",
    color, fontWeight: 600, fontSize: "0.85rem",
  };
}

const formInput = {
  width: "100%", padding: "0.65rem 0.9rem", background: "var(--bg-surface)",
  border: "1px solid var(--border)", borderRadius: 8, fontSize: "0.9rem",
  outline: "none", boxSizing: "border-box",
};
