import { FaCog, FaExclamationTriangle, FaInfoCircle, FaTint, FaSmog, FaWind } from "react-icons/fa";
import ThermoDial from "./ThermoDial";
import EnvironmentRow from "./EnvironmentRow";

const STEP = 1;
const SAFETY_MIN = 60;
const SAFETY_MAX = 75;

// "2h 15m" / "45m" — omits the hours segment entirely under an hour rather
// than showing "0h 45m".
function formatCountdown(untilIso) {
  const totalMinutes = Math.max(0, Math.round((new Date(untilIso).getTime() - Date.now()) / 60000));
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours === 0 ? `${minutes}m` : `${hours}h ${minutes}m`;
}

// idleReason: set when this zone's equipment isn't currently being acted on
// at all (e.g. an air-handler-only zone while gas mode has handed control
// to the boiler, which can't serve or cool this room). The zone's own
// settings (target/schedule/on) still fully work while idle — they just
// take effect again once idle clears — so controls stay live, this only
// adds a visible explanation. onIdleAction, if given, renders a small
// button in that banner (e.g. a shortcut to the mode switch that would
// clear the idle state).
export default function ZoneCard({ zone, onStep, onToggle, onOpenSchedule, onBalanceChange, idleReason, onIdleAction }) {
  const {
    id, label, on, target, currentTemp: current, calling, coolCalling,
    safety = "normal", overridden, overrideUntil, environment,
    damperPercent, damperMoving, balancePercent,
  } = zone;
  const inSafetyOverride = safety !== "normal";
  const hasDamper = damperPercent != null; // boiler zones (simple on/off valves) don't have this

  return (
    <div style={{
      background: inSafetyOverride
        ? "linear-gradient(160deg, var(--tint-danger) 0%, var(--bg-card) 60%)"
        : calling ? "linear-gradient(160deg, var(--tint-warning) 0%, var(--bg-card) 60%)"
        : coolCalling ? "linear-gradient(160deg, var(--tint-info) 0%, var(--bg-card) 60%)"
        : "var(--bg-card)",
      borderRadius: 16,
      border: idleReason
        ? "1px dashed var(--border)"
        : `1px solid ${inSafetyOverride ? "#fca5a5" : calling ? "#fed7aa" : coolCalling ? "#bfdbfe" : "var(--border)"}`,
      boxShadow: "0 1px 3px rgba(0,0,0,0.07)", padding: "1.25rem",
      display: "flex", flexDirection: "column", alignItems: "center", gap: 14,
      transition: "all 0.25s",
    }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", width: "100%" }}>
        <span style={{ fontWeight: 700, color: "var(--text-primary)", fontSize: "1.02rem" }}>{label}</span>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <button onClick={() => onOpenSchedule(id)} aria-label={`${label} schedule`} style={{
            width: 30, height: 30, borderRadius: "50%", border: "none",
            background: "var(--bg-surface-alt)", color: "var(--text-muted)", display: "flex",
            alignItems: "center", justifyContent: "center", cursor: "pointer", fontSize: "0.8rem",
          }}>
            <FaCog />
          </button>
          <button onClick={() => onToggle(id, !on)} aria-label={`${label} ${on ? "on" : "off"}`} style={{
            padding: "0.3rem 0.75rem", borderRadius: 999, border: "none",
            fontWeight: 600, fontSize: "0.78rem", cursor: "pointer",
            background: on ? "#fb923c" : "var(--border)",
            color: on ? "white" : "var(--text-secondary)",
            boxShadow: on ? "0 4px 12px rgba(251,146,60,0.35)" : "none",
            transition: "all 0.2s",
          }}>
            {on ? "On" : "Off"}
          </button>
        </div>
      </div>

      {idleReason && (
        <div style={{
          display: "flex", alignItems: "center", gap: 8, width: "100%", flexWrap: "wrap",
          background: "var(--bg-surface-alt)", border: "1px solid var(--border)", borderRadius: 10,
          padding: "0.5rem 0.7rem", color: "var(--text-secondary)", fontSize: "0.78rem", fontWeight: 600,
        }}>
          <FaInfoCircle style={{ flexShrink: 0 }} />
          <span style={{ flex: 1 }}>{idleReason}</span>
          {onIdleAction && (
            <button onClick={onIdleAction.onClick} style={{
              padding: "0.25rem 0.6rem", borderRadius: 999, border: "none",
              background: "var(--accent)", color: "white", fontWeight: 700, fontSize: "0.72rem", cursor: "pointer",
            }}>
              {onIdleAction.label}
            </button>
          )}
        </div>
      )}

      <ThermoDial
        current={current}
        target={target}
        on={on}
        calling={calling}
        coolCalling={coolCalling}
        safety={safety}
        onStep={delta => onStep(id, Math.max(SAFETY_MIN, Math.min(SAFETY_MAX, target + delta * STEP)))}
        onCommit={value => onStep(id, Math.max(SAFETY_MIN, Math.min(SAFETY_MAX, value)))}
      />

      {environment && (
        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 6 }}>
          <EnvironmentRow icon={FaTint} label="Humidity" unit="%" precision={0}
            min={0} max={100} value={environment.humidity.value} status={environment.humidity.status} />
          <EnvironmentRow icon={FaSmog} label="VOC" unit="" precision={0}
            min={0} max={100} value={environment.voc.value} status={environment.voc.status} />
          <EnvironmentRow icon={FaWind} label="CO2" unit=" ppm" precision={0}
            min={400} max={3000} value={environment.co2.value} status={environment.co2.status} />
        </div>
      )}

      {hasDamper && (
        <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 4 }}>
          <div style={{ display: "flex", justifyContent: "space-between", fontSize: "0.72rem", color: "var(--text-muted)" }}>
            <span>Damper {damperMoving ? `${damperMoving}…` : `${damperPercent}% open`}</span>
            <span>Balance {balancePercent ?? 100}%</span>
          </div>
          <input
            type="range" min={0} max={100} step={5}
            value={balancePercent ?? 100}
            onChange={e => onBalanceChange(id, Number(e.target.value))}
            aria-label={`${label} damper balance`}
            style={{ width: "100%", accentColor: "var(--accent)" }}
          />
        </div>
      )}

      {on && overridden && overrideUntil && !inSafetyOverride && (
        <div style={{
          display: "flex", alignItems: "center", gap: 6, width: "100%",
          background: "var(--tint-info)", border: "1px solid #bfdbfe", borderRadius: 10,
          padding: "0.5rem 0.7rem", color: "#1d4ed8", fontSize: "0.78rem", fontWeight: 600,
        }}>
          Manual override until next schedule: {formatCountdown(overrideUntil)}
        </div>
      )}

      {inSafetyOverride && (
        <div style={{
          display: "flex", alignItems: "center", gap: 6, width: "100%",
          background: "var(--tint-danger)", border: "1px solid #fca5a5", borderRadius: 10,
          padding: "0.5rem 0.7rem", color: "#b91c1c", fontSize: "0.78rem", fontWeight: 700,
        }}>
          <FaExclamationTriangle />
          {safety === "below-min"
            ? `Below ${SAFETY_MIN}°F — forcing heat to prevent freezing, even though this zone is ${on ? "on" : "off"}.`
            : `Above ${SAFETY_MAX}°F — forcing cooling to prevent damage, even though this zone is ${on ? "on" : "off"}.`}
        </div>
      )}
    </div>
  );
}
