import { useState, useEffect, useCallback } from "react";
import { getSettings, putSetting, arrive, leave } from "../api";
import PageHeader from "../components/PageHeader";
import { colors, card, CONTAINER_NARROW, pageContainerStyle } from "../styles/tokens";

const LABEL_MAP = {
  temp_lights:      "Temporary Lights",
  temp_mins:        "Temporary Minutes",
  usersHome:        "Who's Home",
  users_whitelist:  "Users",
  whenAway:         "House Empty Lights",
};

export default function Settings() {
  const [settings, setSettings] = useState({});
  const [newKey,   setNewKey]   = useState("");
  const [newValue, setNewValue] = useState("");
  const [name,     setName]     = useState("pete.buo");

  const fetchSettings = useCallback(async () => {
    const { data } = await getSettings();
    setSettings(data);
  }, []);

  useEffect(() => { fetchSettings(); }, [fetchSettings]);

  const updateSetting = async (key, value) => {
    await putSetting(key, value);
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const addSetting = async () => {
    if (!newKey.trim()) return;
    await updateSetting(newKey, newValue);
    setNewKey(""); setNewValue("");
  };

  const handleTransit = async (action) => {
    if (action === "arrive") await arrive(name);
    else await leave(name);
    fetchSettings();
  };

  const filteredKeys = Object.keys(settings).filter(k =>
    k !== "_id" && k !== "sunset" && k !== "sunrise" &&
    k !== "stargazingStart" && k !== "stargazingEnd" &&
    k !== "lightsOn" && k !== "lights" &&
    (typeof settings[k] !== "object" || Array.isArray(settings[k]))
  );

  return (
    <div style={pageContainerStyle(CONTAINER_NARROW)}>
      <PageHeader title="Settings" />

      {/* Settings list */}
      <div style={cardStyle}>
        <h2 style={cardTitle}>Manage Settings</h2>
        <div>
          {filteredKeys.map(key => (
            <div key={key} style={{
              display: "flex", justifyContent: "space-between", alignItems: "center",
              padding: "0.75rem 0", borderBottom: "1px solid var(--bg-surface-alt)",
            }}>
              <label style={{ fontWeight: 600, color: "var(--text-primary)", fontSize: "0.9rem" }}>
                {LABEL_MAP[key] || key}
              </label>
              <input
                type="text"
                value={Array.isArray(settings[key]) ? settings[key].join(", ") : settings[key]}
                onChange={e => setSettings(p => ({ ...p, [key]: e.target.value }))}
                onBlur={e => updateSetting(key, e.target.value)}
                disabled={Array.isArray(settings[key])}
                style={inputStyle}
              />
            </div>
          ))}
        </div>

        <div style={{ marginTop: "1.5rem", paddingTop: "1.5rem", borderTop: "1px solid var(--bg-surface-alt)" }}>
          <h3 style={{ fontWeight: 600, color: "var(--text-primary)", marginBottom: "0.75rem", fontSize: "0.95rem" }}>Add Setting</h3>
          <div style={{ display: "flex", gap: 8 }}>
            <input placeholder="Key" value={newKey} onChange={e => setNewKey(e.target.value)} style={{ ...inputStyle, flex: 1 }} />
            <input placeholder="Value" value={newValue} onChange={e => setNewValue(e.target.value)} style={{ ...inputStyle, flex: 1 }} />
            <button onClick={addSetting} style={btnPrimary}>Add</button>
          </div>
        </div>
      </div>

      {/* Presence simulation */}
      <div style={{ ...cardStyle, marginTop: "1.25rem" }}>
        <h2 style={cardTitle}>Simulate Transit</h2>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input
            value={name} onChange={e => setName(e.target.value)}
            placeholder="Name" style={{ ...inputStyle, flex: 1 }}
          />
          <button onClick={() => handleTransit("arrive")} style={{ ...btnPrimary, background: "var(--success)" }}>Arrive</button>
          <button onClick={() => handleTransit("leave")}  style={{ ...btnPrimary, background: "var(--danger)" }}>Leave</button>
        </div>
      </div>
    </div>
  );
}

const cardStyle = { ...card, padding: "1.5rem" };
const cardTitle = { fontSize: "1rem", fontWeight: 700, color: colors.textPrimary, marginBottom: "1rem" };
const inputStyle = {
  padding: "0.6rem 0.9rem", background: colors.surface, border: `1px solid ${colors.border}`,
  borderRadius: 8, fontSize: "0.9rem", outline: "none", boxSizing: "border-box",
};
const btnPrimary = {
  padding: "0.6rem 1rem", background: colors.accent, color: "white",
  border: "none", borderRadius: 8, fontWeight: 600, cursor: "pointer", whiteSpace: "nowrap",
};
